def get_axioms() -> list:
    return []


def get_vars() -> dict:
    self = TensorVar('self')
    min = OptVar('min', TensorVar('min' + '.val'))
    max = OptVar('max', TensorVar('max' + '.val'))
    out = TensorVar('out')
    return {'self': self, 'min': min, 'max': max, 'out': out}


def build_solver() -> Solver:
    s = Solver()
    s.add(*get_axioms())
    return s


from model import TensorVar, OptVar, out_is_broadcast, same_shape
def _out_shape_ok():
    self_ = TensorVar('self')
    out = TensorVar('out')
    mn = OptVar('min', TensorVar('min.val'))
    mx = OptVar('max', TensorVar('max.val'))
    minv, maxv = mn.value, mx.value
    # out_is_broadcast per-dim max only exact when no input has a 0-size dim.
    def nb(*ts):
        return And(*[t.numel() > 0 for t in ts])
    return Or(
        out.numel() == 0,
        # neither present: out == self
        And(Not(mn.present), Not(mx.present), same_shape(out, self_)),
        # only min
        And(mn.present, Not(mx.present), nb(self_, minv),
            out_is_broadcast(out, self_, minv)),
        # only max
        And(Not(mn.present), mx.present, nb(self_, maxv),
            out_is_broadcast(out, self_, maxv)),
        # both
        And(mn.present, mx.present, nb(self_, minv, maxv),
            out_is_broadcast(out, self_, minv, maxv)),
    )


def get_constraints() -> list:
    _base = _orig_get_constraints()
    _e = _base[0]
    _inner = _e.arg(0)
    if _inner.decl().name() == 'and':
        _parts = list(_inner.children())
    else:
        _parts = [_inner]
    return [Not(And(*_parts, _out_shape_ok()))]
